from .logger import logger
from .software_components import L2, L3, Egate, Edaemon
from .airphone_uesim import AirPhoneUeSim
from .egate_console import EgateConsole
from .telnet import Telnet
from .sshconnection import managed_from_aliased


class airphone(object):
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    _airphone_controller = None
    _l2 = None
    _l3 = None
    _egate = None
    _edaemon = None
    _l3_output = None
    _l3_error = None

    def configure_l2(self, l2_ssh_alias):
        l2_ssh = managed_from_aliased(l2_ssh_alias)
        self._l2 = L2(l2_ssh)

    def configure_l3(self, l3_ssh_alias, directory_path, port):
        self._configure_remote_process(L3, '_l3', l3_ssh_alias,
                                       directory_path, port)

    def configure_egate(self, egate_ssh_alias, directory_path, port):
        self._configure_remote_process(Egate, '_egate', egate_ssh_alias,
                                       directory_path, port)

    def configure_edaemon(self, edaemon_ssh_alias, directory_path, port):
        self._configure_remote_process(Edaemon, '_edaemon', edaemon_ssh_alias,
                                       directory_path, port)

    def _configure_remote_process(self, component_cls, self_attr_name,
                                  ssh_alias, directory_path, port):
        ssh_connection = managed_from_aliased(ssh_alias)
        component = component_cls(ssh_connection, self._l2, directory_path, port)
        setattr(self, self_attr_name, component)

    def start_airphone(self, egate_console_ip, egate_port, egate_timeout=5.0):
        if (self._l2 is None or self._l3 is None or self._egate is None or self._edaemon is None):
            exc_msg = ("one or more of the required components "
                       "has not been configured.")
            raise RuntimeError(exc_msg)

        egate_port = int(egate_port)
        egate_telnet = Telnet(egate_console_ip, egate_port, egate_timeout)
        egate_controller = EgateConsole(egate_telnet, self._l3, self._edaemon,
                                        self._egate)
        airphone_controller = AirPhoneUeSim(egate_controller)

        airphone_controller.setup()
        self._airphone_controller = airphone_controller

    def stop_airphone(self):
        """
        Stops every software component.
        """
        if self._airphone_controller is None:
            msg = "Airphone controller is not initialized - cannot teardown."
            logger.warn(msg)
        else:
            self._airphone_controller.teardown()
            self._l3_output = self._l3.read_output()
            self._l3_error = self._l3.read_error()

    def read_l3_output(self):
        self._check_l3_output_available()
        logger.debug('L3 output:')
        logger.debug(self._l3_output)
        return self._l3_output

    def read_l3_error(self):
        self._check_l3_output_available()
        logger.debug('L3 error:')
        logger.debug(self._l3_error)
        return self._l3_error

    def _check_l3_output_available(self):
        if self._airphone_controller is None:
            raise RuntimeError("Cannot read L3 output - Airphone not started.")
        if self._l3_output is None or self._l3_error is None:
            raise RuntimeError("You need to run \"Stop Airphone\" first.")

    def read_egate_output(self):
        """ Read at least one byte from Egate console, unless EOF is hit.

        Returns empty string if EOF is hit. Blocks if no data is immediately
        available.
        """
        return self._airphone_controller.read_egate_output()

    def read_egate_output_until(self, expected, timeout=None):
        """ Read output until expected string is hit or timeout is exceeded.

        Timeout is specified in seconds.
        The expected string is included in the returned data.

        Raises EOFError if connection is closed during reading and the expected
        string is not in the buffer.
        Raises socket.timeout if specified timeout is exceeded.
        """
        timeout = float(timeout)
        ac = self._airphone_controller
        return ac.read_egate_output_until(expected, timeout=timeout)

    def read_egate_output_until_prompt(self, timeout=None):
        """ Read output until the prompt string is hit ("EGATE> ").

        Timeout is specified in seconds.
        The prompt string will be stripped from the returned output.

        Raises EOFError if connection is closed during reading and the prompt
        string is not in the buffer.
        Raises socket.timeout if specified timeout is exceeded.
        """
        timeout = float(timeout)
        ac = self._airphone_controller
        return ac.read_egate_output_until_prompt(timeout=timeout)

    def assert_is_in_egate_output(self, expected, msg=None):
        """ Read output, (do a 'read_egate_output()'), and assert that the
        expected string is contained within the captured data.

        Raises AssertionError if the expected string is not in the output.
        If 'msg' argument is specified, the AssertionError will contain that
        message.

        Other raised exceptions and returned value are the same as when using
        'read_egate_output()'.
        """
        output = self.read_egate_output()
        if msg is not None:
            assert expected in output, msg
        else:
            assert expected in output
        return output

    def cfg(self, file):
        self._airphone_controller.configure(file)

    def ue_attach(self, id, phy_cell_id=0, arfcn=0, brs_port0=0,
                  initial_beam_index=0):
        self._airphone_controller.attach(id, phy_cell_id, arfcn, brs_port0,
                                         initial_beam_index)

    def ue_detach(self, id):
        self._airphone_controller.detach(id)

    def traffic_start(self, trf_data_ue=1, trf_data_id=1, dir='ul',
                      trf_id=1, mbps=None, size=None, period_ms=None, burst=None,
                      protocol=None, remote_ip=None):
        """
        Executes egate console with command generated from provided arguments
        :param trf_data_ue: mandatory parameter, default value is 1
        :param trf_data_id: mandatory parameter, default value is 1
        :param dir: mandatory parameter, default value is 'ul',
               possible values are: 'ul', 'dl'
        :param trf_id: optional parameter, default value is 1
        :param mbps: optional parameter, default value is None
        :param size: optional parameter, default value is None
        :param period_ms: optional parameter, default value is None
        :param burst: optional parameter, default value is None
        :param protocol: optional parameter, default value is None,
               possible values are 'udp', 'tcp'
        :param remote_ip: optional parameter, default value is None
        """
        self._airphone_controller.ul_traffic_start(trf_data_ue, trf_data_id, dir,
                                                   trf_id, mbps, size, period_ms,
                                                   burst, protocol, remote_ip)

    def traffic_stop(self, trf_data_ue=1, trf_data_id=1, dir='ul',
                     trf_id=1):
        self._airphone_controller.ul_traffic_stop(trf_data_ue, trf_data_id,
                                                  dir, trf_id)

    def ue_reauth(self, ue_ids, csfb, ambr_ul, ambr_dl, sec_cap):
        """
        MME-initiated reauthentication

        :param ue_ids: List: List of UE ID's for sending X2_RESET message
        :param csfb: Int: (Optional if needed)ON/OFF
        :param ambr_ul: Int: (Optional if needed)Aggregate Maximal Bit Rate, kbps, for all non-GBR bearers of the UE
        :param ambr_dl: Int: (Optional if needed)Aggregate Maximal Bit Rate, kbps, for all non-GBR bearers of the UE
        :param sec_cap: Int: (Optional if needed)UE Security Capabilities

        """
        self._airphone_controller.ue_reauth(ue_ids=ue_ids, csfb=csfb, ambr_ul=ambr_ul, ambr_dl=ambr_dl, sec_cap=sec_cap)

    def ue_ho_param(self, ue_id, ho_mode, enb, rnc, cell, fail, phycell, rsrp,
                    rsrq, earfcn, arfcn, rscp, ecno, pilot_strength):
        """
        Send special measurement report from UE to trigger specified handover procedure.

        :param ue_id: Specified UE ID
        :param ho_mode: One of the following: INTRA_LTE, TO_UTRAN, FROM_UTRAN, TO_HRPD
        :param enb: Local target eNB Id for intra-LTE or UTRAN=>LTE HO
        :param rnc: Local target RNC Id for LTE=>UTRAN HO
        :param cell: Local target cell Id (at eNB or RNC) for intra-LTE or UTRAN=>LTE HO
        :param fail: Force HO (real eNB->...) to fail with RRC:Reestablishment.
        :param phycell: optional physical cell id of target LTE/UTRAN cell
        :param rsrp: Reference Signal Received Power values
        :param rsrq: Reference Signal Received Quality values
        :param earfcn: optional DL EARFCN of target E-UTRAN cell
        :param arfcn: optional DL ARFCN of target UTRAN cell
        :param rscp: Reference Signal Code Power values
        :param ecno: Ec/No value
        :param pilot_strength: Pilot power to total power in the signal bandwidth of the forward channel for CDMA2000
        :return:
        """
        self._airphone_controller.ue_ho_param(
            ue_id=ue_id,
            ho_mode=ho_mode,
            enb=enb,
            rnc=rnc,
            cell=cell,
            fail=fail,
            phycell=phycell,
            rsrp=rsrp,
            rsrq=rsrq,
            earfcn=earfcn,
            arfcn=arfcn,
            rscp=rscp,
            ecno=ecno,
            pilot_strength=pilot_strength,
        )

    def ue_testmode_set_param(self, ue_id,
                              bearer,
                              test_mode,
                              action,
                              profile_index):
        """
        Command for configuring ue test mode.
        :param ue_id: int: Specified UE ID.
        :param bearer: (optional) int: Specified Bearer ID.
        :param test_mode: str: Test mode to be used.
        :param action: (optional) str: Triggers the activation or the deactivation of the test mode.
        :param profile_index: int: Profile index of the test mode.
        """
        self._airphone_controller.ue_testmode_set_param(ue_id=ue_id, bearer=bearer, test_mode=test_mode, action=action,
                                                        profile_index=profile_index)

    def ue_param(self, ue_id,
                 ue_eutra_nr_capabilities=None,
                 ue_nr_capabilities=None,
                 if_rrc_reconf_contains=None,
                 action=None):
        """
        Updates online changeable UE parameters, applicable for UEC.

        :param ue_id: Int: Local UE identifier
        :param ue_eutra_nr_capabilities: String: (Optional) UE EUTRA NR Capabilities, in hex
        :param ue_nr_capabilities: String: (Optional) UE NR Capabilities, in hex
        :param if_rrc_reconf_contains: String: (Optional) Fields present in RRC Connection Reconfiguration
        :param action: Stirng: (Optional) Action to perform on message
        :return:
        """
        self._airphone_controller.ue_param(ue_id=ue_id,
                                           ue_eutra_nr_capabilities=ue_eutra_nr_capabilities,
                                           ue_nr_capabilities=ue_nr_capabilities,
                                           if_rrc_reconf_contains=if_rrc_reconf_contains,
                                           action=action)

    def ue_register_param(self, ue_id, ue_eutra_capabilities=None, ue_nr_capabilities=None, nwslice=None):

        """
         Triggers UE register procedure
        :param ue_id: int: Specified UE ID
        :param ue_eutra_capabilities: (Optional) String UE EUTRA Capabilities, in hex
        :param ue_nr_capabilities: (Optional) String UE NR EUTRA Capabilities, in hex
        :param nwslice: int: id of the Network Slice containing the requested NSSAI

        """
        self._airphone_controller.ue_register_param(ue_id=ue_id,
                                                    ue_eutra_capabilities=ue_eutra_capabilities, nwslice=nwslice)

    def ue_deregister_param(self, ue_id,
                            by=None,
                            ue_deregister_type=None):
        """
        Triggers UE or AMF-initiated deregister procedure.
        :param id: int: Specified UE ID.
        :param by: (optional) String: Device type initiating the deregister procedure(ue|amf).
        :param ue_deregister_type: (optional) String: Type of UE initiated deregister procedure.
        """
        self._airphone_controller.ue_deregister_param(
            ue_id=ue_id,
            by=by,
            ue_deregister_type=ue_deregister_type
        )

    def ue_measurement_send(self, ue_id,
                            meas_id=None,
                            event=None,
                            srsrp=None,
                            srsrq=None,
                            rat=None):
        """
        Send measurements for one to 8 neighbors to eNB.

        :param ue_id: Int: Local UE identifier
        :param meas_id: Int: (Optional) Measurement identity
        :param event: String: (Optional) Event type
        :param srsrp: Int: (Optional) RSRP value for serving (-140 dBm .. -44 dBm, step 1 dBm).
        :param srsrq: Int: (Optional) RSRQ values serving (-19.5 dB .. -3 dB, step 0.5 dB).
        :param rat: String: (Optional) Radio access technology assigned
        :return:
        """
        self._airphone_controller.ue_measurement_send(ue_id=ue_id,
                                                      meas_id=meas_id,
                                                      event=event,
                                                      srsrp=srsrp,
                                                      srsrq=srsrq,
                                                      rat=rat)

    def ue_nr_measurement_send(self, ue_id,
                               meas_id=None,
                               rat=None,
                               event=None,
                               srsrp=None,
                               srsrq=None,
                               ssinr=None,
                               phycell_id=None,
                               nrsrp=None,
                               nrsrq=None,
                               nsinr=None,
                               addtion=None
                               ):
        """
        Send NR measurements to gNB for 1 to 8 neighbors.

        :param ue_id: Int: Local UE identifier
        :param meas_id: Int: (Optional) Measurement identity
        :param rat: String: (Optional) Radio access technology assigned
        :param event: String: (Optional) Event type
        :param srsrp: Int: (Optional) RSRP value for serving cell
        :param srsrq: Int: (Optional) RSRQ value for serving cell
        :param ssinr: Int: (Optional) SINR value for serving cell
        :param phycell_id: Int: (Optional) Physical cell id. Multiple neighbors
                                           maybe specified by grouping according to phycell_id
        :param nrsrp: Int: (Optional) RSRP value for neighbor cell(s)
        :param nrsrq: Int: (Optional) RSRQ value for neighbor cell(s)
        :param nsinr: Int: (Optional) SINR value for neighbor cell(s)
        :param addtion: String: (Optional) the string want to added at the end of cmd line.
        :return:
        """
        self._airphone_controller.ue_nr_measurement_send(
            ue_id=ue_id,
            meas_id=meas_id,
            rat=rat,
            event=event,
            srsrp=srsrp,
            srsrq=srsrq,
            ssinr=ssinr,
            phycell_id=phycell_id,
            nrsrp=nrsrp,
            nrsrq=nrsrq,
            nsinr=nsinr,
            addtion=addtion
        )

    def enb_ue_dc_modify(self, ue_id, by, cause, bearer=None, ambr=None,
                         bearer_to_add=None,
                         bearer_to_modify=None,
                         bearer_to_release=None,
                         scg_config_query=None):
        """
        Command to trigger LTE-NR dual connectivity modification

        :param ue: Int: Specified UE ID
        :param by: String: Determines the initiator of the DC procedure
        :param cause: String: Cause for the DC procedure
        :param bearer: (Optional) Int: Bearer id
        :param ambr: (Optional) Int: Update aggregate max bit rate, DL:UL
        :param bearer_to_add: (Optional) Int: To Added Bearer ID List
        :param bearer_to_modify: (Optional) Int: To Modified Bearer ID List
        :param bearer_to_release: (Optional) Int: To Released Bearer ID List
        :param scg_config_query: (Optional) String: Send X2AP SGNB MODIFICATION
                                                    REQUEST with SCG Configuration Query
        :return:
        """
        self._airphone_controller.enb_ue_dc_modify(
            ue_id=ue_id,
            by=by,
            cause=cause,
            bearer=bearer,
            ambr=ambr,
            bearer_to_add=bearer_to_add,
            bearer_to_modify=bearer_to_modify,
            bearer_to_release=bearer_to_release,
            scg_config_query=scg_config_query,
        )

    def ue_dc_start(self, ue_cm_id=1, bearer_cm_id=1, gNB_id=2,
                    pci=None, arfcn=None, unsupp_SgNbAddReq_opt=None,
                    no_sgnb_reconf_complete=None):
        """
        triggers dual connectivity

        :param ue_cm_id: Ue Identifier
        :param bearer_cm_id: Bearer Identifier
        :param gNB_id: 	local gNB Identifier in configuration file
        :param pci: (optional)Physical cell id of target 5GNB cell
        :param arfcn: (optional)ARFCN of target 5GNB cell
        :param unsupp_SgNbAddReq_opt: (optional)SgNB addition request option
                                      to be simulated
        :param no_sgnb_reconf_complete: (Optional)SgNbAdditionReq option to be simulated,
                                        i.e. normal, or failing scenarios
        """
        self._airphone_controller.ue_dc_start(ue_cm_id=ue_cm_id,
                                              bearer_cm_id=bearer_cm_id,
                                              gnb_id=gNB_id,
                                              pci=pci,
                                              arfcn=arfcn,
                                              unsupp_SgNbAddReq_opt=unsupp_SgNbAddReq_opt,
                                              no_sgnb_reconf_complete=no_sgnb_reconf_complete)

    def ue_dc_start_error(self, ue_cm_id):
        """
        This command will trigger UE Dual Connectivity failed scenario.

        :param ue_cm_id: Int: UE identifier that needs SgNB Addition Request
        :return:
        """
        self._airphone_controller.ue_dc_start_error(ue_cm_id=ue_cm_id)

    def ue_enb_endc_param(self, ue_id,
                          p_max_nr=None,
                          p_max_eutra=None,
                          unsupported_ext_hdr_type=None,
                          at=None,
                          candidate_cells_mn_hex_for_menb_ho=None):
        """
        Updates online changeable UE parameters, applicable for eNB endc.

        :param id: Int: Specified UE ID
        :param p_max_nr: Int: (Optional) PMaxNr value for the DC procedure
        :param p_max_eutra: Int: (Optional) PMaxEutra value for the DC procedure
        :param unsupported_ext_hdr_type: String (Optional) Configure MeNB to add GTPU extension header types
                                         not supported by SgNB
        :param at: String (Optional) Specifies when to use unsupported GTPU extension header types
        :return:
        """
        self._airphone_controller.ue_enb_endc_param(
            ue_id=ue_id,
            p_max_nr=p_max_nr,
            p_max_eutra=p_max_eutra,
            unsupported_ext_hdr_type=unsupported_ext_hdr_type,
            at=at,
            candidate_cells_mn_hex_for_menb_ho=candidate_cells_mn_hex_for_menb_ho
        )

    def enb_ue_dc_release(self, ue_id, bearer, by, cause):
        """
        Command to trigger LTE-NR dual connectivity release

        :param ue_id: Int: Specified UE ID
        :param bearer: Int: Bearer id
        :param by: String: Determines the initiator of the DC procedure
        :param cause: String: Cause for the DC procedure
        :return:
        """
        self._airphone_controller.enb_ue_dc_release(
            ue_id=ue_id,
            bearer=bearer,
            by=by,
            cause=cause
        )

    def ue_ctrl_add_ue_dc_param(self, ue_id, if_ctrl_add_ue_dc_contains,
                                action=None, delay=None):
        """
        Configures rules to specify action and/or delay processing of the message
        based on presence of certain IEs in CtrlAddUeDc messages

        ATTENTION: in Lteemu egate documentation, action and delay should not be specific at the same time.
        unless for test requirement.

        :param ue_id: Int: UE id to which failure scenario will apply
        :param if_ctrl_add_ue_dc_contains: String: fields present in CtrlAddUeDc message
        :param action: String: (Optional) MeNB behavior to be simulated
        :param delay: Int: (Optional) delay in ms when sending for CtrlAddUeDc message
        :return:
        """
        self._airphone_controller.ue_ctrl_add_ue_dc_param(
            ue_id=ue_id,
            if_ctrl_add_ue_dc_contains=if_ctrl_add_ue_dc_contains,
            action=action,
            delay=delay
        )

    def ue_dc_rlf(self, ue_id, failure_type, at=None, meas_result_scg=None):
        """
        Trigger a radio link failure in a UE in dual connectivity

        :param ue_id: Int: Specified UE ID
        :param failure_type: String: Cause of radio link failure
        :param at: String: (Optional) Specifies where UE detected radio link failure
        :param meas_result_scg: String: (Optional) Hex stream for NR-RRC: MeasResultSCG-Failure message
        :return:
        """
        self._airphone_controller.ue_dc_rlf(
            ue_id=ue_id,
            failure_type=failure_type,
            at=at,
            meas_result_scg=meas_result_scg
        )

    def ue_pdu_session_setup(self, ue_id, nwslice=None):
        """
        Triggers UE PDU session setup
        :param ue_id: int: Specified UE ID
        :param nwslice: int (Optional): Requested Network Slice for the PDU Session

        """
        self._airphone_controller.ue_pdu_session_setup(
            ue_id=ue_id,
            nwslice=nwslice
        )

    def ue_pdu_session_release(self, ue_ids, pdu, by=None):
        """
        Triggers UE OR AMF intiated PDU Session Release procedure
        :param ue_ids: int: Specified UE ID(s)
        :param pdu: int: PDU Session ID to be released
        :param by: (Optional) String: Device type initiating the procedure

        """
        self._airphone_controller.ue_pdu_session_release(ue_ids=ue_ids,
                                                         pdu=pdu,
                                                         by=by)
